// PayPal REST sandbox for the wallet experiment's live flow (F8), through PayPal's official server SDK
// (@paypal/paypal-server-sdk, generated by APIMatic). The secret stays on the server.

import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrdersController,
  PaypalExperienceUserAction,
  PaypalPaymentTokenCustomerType,
  PaypalPaymentTokenUsageType,
  PaypalWalletContextShippingPreference,
  StoreInVaultInstruction,
  UsagePattern,
  VaultController,
  VaultTokenRequestType,
} from "@paypal/paypal-server-sdk";

const LIVE_FILE = ".data/wallet-live.json";
const SETUP_FILE = ".data/wallet-setup.json";
const DEBUG_FILE = ".data/wallet-paypal-debug.json";
const base = () => process.env.PAYPAL_API_BASE?.trim() || "https://api-m.sandbox.paypal.com";
const appUrl = () => process.env.APP_URL?.trim() || "http://localhost:3000";

export type LiveEvent = {
  at: string;
  kind: "payment" | "renewal" | "saved";
  orderId: string;
  status: string;
  amount: string;
  vaultId?: string | null;
  vaultStatus?: string | null; // VAULTED, APPROVED (saving still in progress), or null (PayPal didn't save)
  customerId?: string | null; // PayPal customer ID, used to look the saved wallet up later
  error?: string;
};

export function paypalConfigured() {
  return Boolean(process.env.PAYPAL_CLIENT_ID?.trim() && process.env.PAYPAL_CLIENT_SECRET?.trim());
}

let sdk: { orders: OrdersController; vault: VaultController } | null = null;
function api() {
  if (!sdk) {
    const client = new Client({
      clientCredentialsAuthCredentials: { oAuthClientId: process.env.PAYPAL_CLIENT_ID!.trim(), oAuthClientSecret: process.env.PAYPAL_CLIENT_SECRET!.trim() },
      environment: Environment.Sandbox,
      timeout: 30_000,
    });
    sdk = { orders: new OrdersController(client), vault: new VaultController(client) };
  }
  return sdk;
}

// Keeps PayPal's raw replies (no secrets) so any failure can be diagnosed from what PayPal actually said.
function debug(step: string, body: unknown) {
  mkdirSync(".data", { recursive: true });
  const prev = existsSync(DEBUG_FILE) ? (JSON.parse(readFileSync(DEBUG_FILE, "utf8")) as unknown[]) : [];
  writeFileSync(DEBUG_FILE, JSON.stringify([...prev.slice(-19), { at: new Date().toISOString(), step, body }], null, 2));
}

// Runs one SDK call, logs PayPal's reply, and turns SDK errors into PayPal's own message.
async function run<T>(step: string, fn: () => Promise<{ result: T; body?: unknown }>): Promise<T> {
  try {
    const res = await fn();
    debug(step, { ok: true, body: res.body });
    return res.result;
  } catch (err) {
    if (err instanceof ApiError) {
      const raw = typeof err.body === "string" ? err.body : "";
      debug(step, { ok: false, status: err.statusCode, body: raw });
      let msg = "request failed";
      try {
        const j = JSON.parse(raw) as { message?: string; name?: string; details?: { issue?: string; description?: string }[] };
        const details = j.details?.map((d) => `${d.issue}: ${d.description}`).join("; ");
        msg = `${j.message ?? j.name ?? msg}${details ? ` (${details})` : ""}`;
      } catch {}
      throw new Error(`PayPal ${err.statusCode}: ${msg}`);
    }
    throw err;
  }
}

// Short-lived ID token the PayPal button script needs (data-user-id-token) to save a wallet with a purchase.
// The SDK has no call for an ID token, so this one request stays hand-written.
export async function idToken(): Promise<string> {
  const auth = Buffer.from(`${process.env.PAYPAL_CLIENT_ID!.trim()}:${process.env.PAYPAL_CLIENT_SECRET!.trim()}`).toString("base64");
  const res = await fetch(`${base()}/v1/oauth2/token`, { method: "POST", headers: { Authorization: `Basic ${auth}` }, body: new URLSearchParams({ grant_type: "client_credentials", response_type: "id_token" }), signal: AbortSignal.timeout(20_000) });
  const j = (await res.json()) as { id_token?: string };
  if (!res.ok || !j.id_token) throw new Error(`PayPal didn't return an ID token (${res.status}).`);
  return j.id_token;
}

// When PayPal reports the wallet as APPROVED (saving still in progress), look it up by customer ID instead of a webhook.
export async function findSavedWallet(customerId: string, tries = 5): Promise<string | null> {
  for (let i = 0; i < tries; i++) {
    const r = await run("listCustomerPaymentTokens", () => api().vault.listCustomerPaymentTokens({ customerId }));
    const t = r.paymentTokens?.find((p) => p.paymentSource?.paypal);
    if (t?.id) return t.id;
    await new Promise((res) => setTimeout(res, 2000));
  }
  return null;
}

const amountOf = (value: string) => ({ currencyCode: "USD", value });

// The customer's renewal payment, saving the wallet for future renewals once it succeeds.
export async function createOrder(amount: string) {
  const o = await run("createOrder", () =>
    api().orders.createOrder({
      paypalRequestId: crypto.randomUUID(),
      body: {
        intent: CheckoutPaymentIntent.Capture,
        purchaseUnits: [{ amount: amountOf(amount), description: "SecondMint demo renewal" }],
        paymentSource: {
          paypal: {
            attributes: { vault: { storeInVault: StoreInVaultInstruction.OnSuccess, usageType: PaypalPaymentTokenUsageType.Merchant, customerType: PaypalPaymentTokenCustomerType.Consumer } },
            experienceContext: {
              returnUrl: `${appUrl()}/wallet`,
              cancelUrl: `${appUrl()}/wallet`,
              shippingPreference: PaypalWalletContextShippingPreference.NoShipping,
              userAction: PaypalExperienceUserAction.PayNow,
            },
          },
        },
      },
    }),
  );
  return o.id!;
}

export async function captureOrder(orderId: string): Promise<LiveEvent> {
  const c = await run("captureOrder", () => api().orders.captureOrder({ id: orderId, paypalRequestId: crypto.randomUUID() }));
  const v = c.paymentSource?.paypal?.attributes?.vault;
  const customerId = v?.customer?.id ?? null;
  let vaultId = v?.id ?? null;
  if (!vaultId && customerId) vaultId = await findSavedWallet(customerId).catch(() => null);
  return {
    at: new Date().toISOString(),
    kind: "payment",
    orderId: c.id ?? orderId,
    status: String(c.status ?? ""),
    amount: c.purchaseUnits?.[0]?.payments?.captures?.[0]?.amount?.value ?? "",
    vaultId,
    vaultStatus: vaultId ? "VAULTED" : (v?.status ? String(v.status) : null),
    customerId,
  };
}

// The next renewal, charged to the saved wallet with no customer present.
export async function chargeSavedWallet(vaultId: string, amount: string): Promise<LiveEvent> {
  const o = await run("createOrder (saved wallet)", () =>
    api().orders.createOrder({
      paypalRequestId: crypto.randomUUID(),
      body: {
        intent: CheckoutPaymentIntent.Capture,
        purchaseUnits: [{ amount: amountOf(amount), description: "SecondMint demo next renewal (saved wallet)" }],
        paymentSource: { paypal: { vaultId } },
      },
    }),
  );
  let id = o.id!;
  let status = String(o.status ?? "");
  if (status !== "COMPLETED") {
    const c = await run("captureOrder (saved wallet)", () => api().orders.captureOrder({ id, paypalRequestId: crypto.randomUUID() }));
    id = c.id ?? id;
    status = String(c.status ?? "");
  }
  return { at: new Date().toISOString(), kind: "renewal", orderId: id, status, amount, vaultId };
}

// Step 1: ask PayPal for a setup token and the buyer approval link. Saves no payment.
export async function createSetupToken(): Promise<{ id: string; approveUrl: string }> {
  const j = await run("createSetupToken", () =>
    api().vault.createSetupToken({
      paypalRequestId: crypto.randomUUID(),
      body: {
        paymentSource: {
          paypal: {
            description: "Save your PayPal wallet for future SecondMint renewals",
            permitMultiplePaymentTokens: false,
            usagePattern: UsagePattern.Immediate,
            usageType: PaypalPaymentTokenUsageType.Merchant,
            customerType: PaypalPaymentTokenCustomerType.Consumer,
            experienceContext: { brandName: "SecondMint Demo", returnUrl: `${appUrl()}/wallet?vault=return`, cancelUrl: `${appUrl()}/wallet?vault=cancel` },
          },
        },
      },
    }),
  );
  const approveUrl = j.links?.find((l) => l.rel === "approve")?.href;
  if (!j.id || !approveUrl) throw new Error("PayPal returned no approval link for the setup token.");
  // Kept server-side: the exchange uses this ID, never one taken from the return URL.
  mkdirSync(".data", { recursive: true });
  writeFileSync(SETUP_FILE, JSON.stringify({ id: j.id, createdAt: new Date().toISOString() }));
  return { id: j.id, approveUrl };
}

// Step 2 (after the buyer approves): exchange the setup token for the reusable payment token, then read it back.
export async function exchangeSetupToken(): Promise<LiveEvent> {
  if (!existsSync(SETUP_FILE)) throw new Error("No pending save request. Click 'Save PayPal wallet' first.");
  const { id } = JSON.parse(readFileSync(SETUP_FILE, "utf8")) as { id: string };
  const t = await run("createPaymentToken", () =>
    api().vault.createPaymentToken({ paypalRequestId: crypto.randomUUID(), body: { paymentSource: { token: { id, type: VaultTokenRequestType.SetupToken } } } }),
  );
  const check = await run("getPaymentToken", () => api().vault.getPaymentToken(t.id!));
  rmSync(SETUP_FILE, { force: true });
  return { at: new Date().toISOString(), kind: "saved", orderId: id, status: check.id === t.id ? "VAULTED" : "UNVERIFIED", amount: "0.00", vaultId: t.id ?? null, vaultStatus: "VAULTED", customerId: t.customer?.id ?? null };
}

export const loadLive = (): LiveEvent[] => (existsSync(LIVE_FILE) ? (JSON.parse(readFileSync(LIVE_FILE, "utf8")) as LiveEvent[]) : []);
export function appendLive(e: LiveEvent) {
  mkdirSync(".data", { recursive: true });
  writeFileSync(LIVE_FILE, JSON.stringify([...loadLive(), e], null, 2));
}
